class Solution {
public:
    int numberOfGoodSubarraySplits(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        vector<int> indices;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (nums[i] == 1) indices.push_back(i);
        }
        if (indices.empty()) return 0;
        long long ans = 1;
        for (int i = 0; i < (int)indices.size() - 1; ++i) {
            ans = (ans * (indices[i + 1] - indices[i])) % MOD;
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    public int numberOfGoodSubarraySplits(int[] nums) {
        final int MOD = 1_000_000_007;
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 1) indices.add(i);
        }
        if (indices.isEmpty()) return 0;
        long ans = 1;
        for (int i = 0; i < indices.size() - 1; i++) {
            ans = (ans * (indices.get(i + 1) - indices.get(i))) % MOD;
        }
        return (int) ans;
    }
}

var numberOfGoodSubarraySplits = function(nums) {
    const MOD = 1000000007n;
    const indices = [];
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === 1) indices.push(BigInt(i));
    }
    if (indices.length === 0) return 0;
    let ans = 1n;
    for (let i = 0; i < indices.length - 1; i++) {
        ans = (ans * (indices[i + 1] - indices[i])) % MOD;
    }
    return Number(ans);
};
